    /* -------------------------------------------------------------
     * 1. Enable peripheral clocks & configure independent clock source
     * ------------------------------------------------------------- */
    /* Select HSI16 (16 MHz) as the independent I2C3 kernel clock (RCC->CCIPR: I2C3SEL = 10b) */
    RCC->CCIPR &= ~RCC_CCIPR_I2C3SEL_Msk;
    RCC->CCIPR |= (2U << RCC_CCIPR_I2C3SEL_Pos);

    /* Enable GPIO port clocks: GPIOA (PA8) and GPIOC (PC8, PC9) */
    RCC->AHB2ENR |= (RCC_AHB2ENR_GPIOAEN | RCC_AHB2ENR_GPIOCEN);

    /* Enable timer and I2C peripheral clocks: TIM1 on APB2, I2C3 on APB1 */
    RCC->APB2ENR |= RCC_APB2ENR_TIM1EN;
    RCC->APB1ENR1 |= RCC_APB1ENR1_I2C3EN;

    /* -------------------------------------------------------------
     * 2. Configure PA8 for TIM1_CH1 (AF6)
     * ------------------------------------------------------------- */
    /* Alternate function mode (MODER8 = 10b) */
    GPIOA->MODER &= ~GPIO_MODER_MODE8_Msk;
    GPIOA->MODER |= GPIO_MODER_MODE8_1;
    /* Output type: Push-Pull (OT8 = 0) */
    GPIOA->OTYPER &= ~GPIO_OTYPER_OT8;
    /* Output speed: Very High Speed (OSPEED8 = 11b) */
    GPIOA->OSPEEDR |= (GPIO_OSPEEDR_OSPEED8_0 | GPIO_OSPEEDR_OSPEED8_1);
    /* No pull-up, no pull-down (PUPD8 = 00b) */
    GPIOA->PUPDR &= ~GPIO_PUPDR_PUPD8_Msk;
    /* Alternate function 6 (AF6) in AFR[1] (AFRH bits 3:0) */
    GPIOA->AFR[1] &= ~GPIO_AFRH_AFSEL8_Msk;
    GPIOA->AFR[1] |= (6U << GPIO_AFRH_AFSEL8_Pos);

    /* -------------------------------------------------------------
     * 3. Configure TIM1 for 20 kHz PWM, 25% duty cycle on Channel 1
     *    Timer clock = 170 MHz.
     *    ARR = 8499 (period = 8500 counts -> 20 kHz).
