### Bare-Metal C Code

```c
#include "stm32g4xx.h"

/**
 * @brief Initialize USART3 on PB10 (TX) and PB11 (RX) at 115200 baud.
 *        Configuration: 8 data bits, no parity, 1 stop bit, 16x oversampling,
 *        TX and RX enabled, BRR configured before USART enable.
 *        Clock: PCLK1 = 170 MHz.
 */
void usart3_debug_init(void)
{
    /* 1. Enable GPIOB peripheral clock on AHB2 */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOBEN;

    /* 2. Configure PB10 and PB11 as Alternate Function mode (MODER = 10b) */
    GPIOB->MODER &= ~(GPIO_MODER_MODE10_Msk | GPIO_MODER_MODE11_Msk);
    GPIOB->MODER |= (2U << GPIO_MODER_MODE10_Pos) | (2U << GPIO_MODER_MODE11_Pos);

    /* Configure high output speed for PB10 and PB11 */
    GPIOB->OSPEEDR |= (2U << GPIO_OSPEEDR_OSPEED10_Pos) | (2U << GPIO_OSPEEDR_OSPEED11_Pos);

    /* Enable pull-up resistor on PB11 (RX) to keep the bus idle-high when disconnected */
    GPIOB->PUPDR &= ~GPIO_PUPDR_PUPD11_Msk;
    GPIOB->PUPDR |= (1U << GPIO_PUPDR_PUPD11_Pos);

    /* 3. Assign Alternate Function 7 (USART3) to PB10 and PB11 in AFRH (AFR[1]) */
    GPIOB->AFR[1] &= ~((0xFU << GPIO_AFRH_AFSEL10_Pos) | (0xFU << GPIO_AFRH_AFSEL11_Pos));
    GPIOB->AFR[1] |= (7U << GPIO_AFRH_AFSEL10_Pos) | (7U << GPIO_AFRH_AFSEL11_Pos);

    /* 4. Enable USART3 peripheral clock on APB1 */
    RCC->APB1ENR1 |= RCC_APB1ENR1_USART3EN;

    /* 5. Set Baud Rate to 115200 baud before enabling the peripheral:
     *    USART3 kernel clock = PCLK1 = 170 MHz
     *    OVER8 = 0 (16x oversampling)
     *    BRR = 170,000,000 / 115,200 = 1475.694 -> 1476 (0x05C4)
     *    Actual baud = 115176 baud (error ~0.02%)
     */
    USART3->BRR = 1476U;

    /* 6. Configure CR2: 1 Stop bit (STOP[1:0] = 00b) */
    USART3->CR2 &= ~USART_CR2_STOP_Msk;

    /* 7. Configure CR1:
     *    - Word length: 8 data bits (M[1:0] = 00b)
     *    - Parity control disabled (PCE = 0)
     *    - Oversampling by 16 (OVER8 = 0)
     *    - Transmitter enable (TE = 1)
     *    - Receiver enable (RE = 1)
     *    - USART enable (UE = 1)
     */
    USART3->CR1 = USART_CR1_TE | USART_CR1_RE | USART_CR1_UE;
}
