### Bare-Metal C Code

```c
#include "stm32g4xx.h"

/**
 * @brief Initialize USART1 as a serial console at 115200 8N1.
 *        TX on PA9 (AF7), RX on PA10 (AF7).
 *        Clock: PCLK2 = 170 MHz.
 */
void console_usart1_init(void)
{
    /* 1. Enable peripheral clock for GPIOA and USART1 */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN;
    RCC->APB2ENR |= RCC_APB2ENR_USART1EN;

    /* 2. Configure PA9 (TX) and PA10 (RX) in Alternate Function mode (AF7) */
    /* Set MODER: 0b10 (AF) for PA9 and PA10 */
    GPIOA->MODER &= ~((3U << GPIO_MODER_MODE9_Pos) | (3U << GPIO_MODER_MODE10_Pos));
    GPIOA->MODER |=  ((2U << GPIO_MODER_MODE9_Pos) | (2U << GPIO_MODER_MODE10_Pos));

    /* Very high output speed for TX (PA9) */
    GPIOA->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED9_Pos);

    /* Pull-up for RX (PA10) to maintain line idle high */
    GPIOA->PUPDR &= ~((3U << GPIO_PUPDR_PUPD9_Pos) | (3U << GPIO_PUPDR_PUPD10_Pos));
    GPIOA->PUPDR |=  (1U << GPIO_PUPDR_PUPD10_Pos);

    /* Assign AF7 (USART1) to PA9 and PA10 in AFR[1] (AFRH) */
    GPIOA->AFR[1] &= ~((0xFU << ((9U - 8U) * 4U)) | (0xFU << ((10U - 8U) * 4U)));
    GPIOA->AFR[1] |=  ((7U    << ((9U - 8U) * 4U)) | (7U    << ((10U - 8U) * 4U)));

    /* 3. Configure USART1 */
    /* Ensure USART1 is disabled before writing BRR and configuration */
    USART1->CR1 = 0U;

    /* Baud rate = 115200: BRR = 170,000,000 / 115200 = 1476 (0x05C4) */
    USART1->BRR = 170000000UL / 115200UL;

    /* 1 Stop bit */
    USART1->CR2 = 0U;

    /* No flow control or half-duplex settings */
    USART1->CR3 = 0U;

    /* 8 data bits (M0=0, M1=0), no parity (PCE=0), oversampling by 16 (OVER8=0),
     * enable Transmitter (TE), Receiver (RE), and USART (UE) */
    USART1->CR1 = USART_CR1_TE | USART_CR1_RE | USART_CR1_UE;
}

/**
 * @brief Transmit a single character over USART1 (polling TXE).
 */
void console_putchar(char c)
{
    while (!(USART1->ISR & USART_ISR_TXE_TXFNF)) {
        /* Busy wait until transmit data register is empty */
    }
    USART1->TDR = (uint8_t)c;
}

/**
 * @brief Receive a single character over USART1 (polling RXNE).
 */
char console_getchar(void)
{
    while (!(USART1->ISR & USART_ISR_RXNE_RXFNE)) {
        /* Busy wait until data is received */
    }
    return (char)(USART1->RDR & 0xFFU);
}
