#include "stm32g4xx.h"

/**
 * @brief Initialize PA6 (TIM3_CH1) as a 1 kHz PWM output at 50% duty cycle.
 *        - Edge-aligned PWM mode 1
 *        - Active-high output
 *        - Timer clock: 170 MHz (PCLK1 = 170 MHz, APB1 prescaler = 1)
 */
void tim3_ch1_pwm_init(void)
{
    /* 1. Enable peripheral clocks for GPIOA and TIM3 */
    RCC->AHB2ENR  |= RCC_AHB2ENR_GPIOAEN;
    RCC->APB1ENR1 |= RCC_APB1ENR1_TIM3EN;

    /* 2. Configure PA6 in Alternate Function mode (AF2: TIM3_CH1) */
    /* Set MODER: 0b10 (Alternate Function) for pin 6 */
    GPIOA->MODER &= ~(3U << GPIO_MODER_MODE6_Pos);
    GPIOA->MODER |=  (2U << GPIO_MODER_MODE6_Pos);

    /* Output type: Push-Pull (0) */
    GPIOA->OTYPER &= ~(1U << GPIO_OTYPER_OT6_Pos);

    /* Output speed: Very High (0b11) */
    GPIOA->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED6_Pos);

    /* No pull-up, no pull-down */
    GPIOA->PUPDR &= ~(3U << GPIO_PUPDR_PUPD6_Pos);

    /* Alternate function AF2 (TIM3_CH1) in AFR[0] (AFRL) for PA6 */
    GPIOA->AFR[0] &= ~(0xFU << GPIO_AFRL_AFSEL6_Pos);
    GPIOA->AFR[0] |=  (2U    << GPIO_AFRL_AFSEL6_Pos);

    /* 3. Configure TIM3 for 1 kHz PWM, 50% duty cycle */
    /* Stop timer and reset CR1 */
    TIM3->CR1 = 0U;

    /* Prescaler: PSC = 3 (clock divided by 3 + 1 = 4) */
    TIM3->PSC = 3U;

    /* Auto-reload: ARR = (170000000 / (4 * 1000)) - 1 = 42499 */
    TIM3->ARR = 42499U;

    /* Pulse width: CCR1 = (42499 + 1) * 50 / 100 = 21250 */
    TIM3->CCR1 = 21250U;

    /* Configure Channel 1:
     * - CC1S = 00 (Channel 1 configured as output)
     * - OC1M = 0110b (PWM mode 1: active while CNT < CCR1, inactive otherwise)
     * - OC1PE = 1 (Output compare 1 preload enable)
     */
    TIM3->CCMR1 &= ~(TIM_CCMR1_CC1S_Msk | TIM_CCMR1_OC1M_Msk);
    TIM3->CCMR1 |=  ((6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE);

    /* Configure Output:
     * - CC1P = 0 (Active-high output polarity)
     * - CC1E = 1 (Enable Channel 1 output on external pin)
     */
    TIM3->CCER &= ~TIM_CCER_CC1P;
    TIM3->CCER |=  TIM_CCER_CC1E;

    /* Enable Auto-reload preload (ARPE) in CR1 */
    TIM3->CR1 |= TIM_CR1_ARPE;

    /* Generate an update event to preload PSC, ARR, and CCR1 shadow registers */
    TIM3->EGR = TIM_EGR_UG;

    /* Start counter */
    TIM3->CR1 |= TIM_CR1_CEN;
}
